// VALIDAÇÃO UNIVERSAL (Busca em todos os 34 imóveis)
window.validarCodigoGeral = async (codigo) => {
    if (!codigo) return alert("Por favor, digite ou escaneie um código.");
    
    const codigoLimpo = codigo.trim().toUpperCase();
    let encontrado = false;

    // Varre todos os imóveis carregados do Firestore
    todosImoveis.forEach(item => {
        const i = item.data;

        // Busca no Histórico de Recibos
        if (i.historicoRecibos && i.historicoRecibos[codigoLimpo]) {
            const dados = i.historicoRecibos[codigoLimpo];
            encontrado = true;
            alert(`✅ RECIBO AUTÊNTICO\n\nLocatário: ${i.inquilino}\nReferência: ${dados.mes}\nValor: R$ ${i.valor}`);
        } 
        
        // Busca no Histórico de Contratos
        else if (i.historicoContratos && i.historicoContratos[codigoLimpo]) {
            const dados = i.historicoContratos[codigoLimpo];
            encontrado = true;
            alert(`✅ CONTRATO AUTÊNTICO\n\nLocatário: ${i.inquilino}\nImóvel: ${i.endereco.completo || i.endereco}`);
        }
    });

    if (!encontrado) {
        alert("❌ CÓDIGO INVÁLIDO\nEste documento não consta no sistema NJ Imóveis.");
    }
};

// FUNÇÃO QUE PROCESSA A ESCOLHA DO MÊS E CHAMA A GERAÇÃO DO PDF
window.processarReciboManual = () => {
    const id = document.getElementById('idImovelRecibo').value;
    const dataEscolhida = document.getElementById('mesReferenciaRecibo').value; // Captura o valor do input tipo "month"
    
    if(!dataEscolhida) return alert("Por favor, selecione o mês e o ano!");

    // Converte "2026-04" para "ABRIL DE 2026"
    const [ano, mes] = dataEscolhida.split('-');
    const dataRef = new Date(ano, mes - 1, 15); // Dia 15 para evitar bugs de fuso horário
    const mesExtenso = dataRef.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();

    // Fecha o modal de escolha
    const modalElement = document.getElementById('modalEscolherMes');
    const modalInstancia = bootstrap.Modal.getInstance(modalElement);
    if(modalInstancia) modalInstancia.hide();

    // Chama a função principal de gerar o PDF que criamos antes
    window.gerarReciboPDF(id, mesExtenso);
};

// FUNÇÃO QUE ABRE A CAMERA PARA VERIFICAÇÃO
let html5QrCodeScanner = null;

window.iniciarCamera = () => {
    const btn = document.getElementById('btnIniciarCamera');
    btn.disabled = true;
    btn.innerText = "Carregando câmera...";

    html5QrCodeScanner = new Html5Qrcode("reader");
    
    const qrCodeSuccessCallback = (decodedText) => {
        // Quando o QR Code é lido, preenche o campo e valida automaticamente
        document.getElementById('inputValidarCodigo').value = decodedText;
        window.pararCamera();
        
        // --- ALTERAÇÃO AQUI: Chama a função unificada em vez de apenas recibo ---
        window.validarCodigoGeral(decodedText); 
    };

    const config = { fps: 10, qrbox: { width: 200, height: 200 } };

    // Tenta iniciar com a câmera traseira (environment)
    html5QrCodeScanner.start({ facingMode: "environment" }, config, qrCodeSuccessCallback)
        .then(() => {
            btn.style.display = 'none'; 
        })
        .catch((err) => {
            console.error("Erro na câmera:", err);
            alert("Não foi possível acessar a câmera. Verifique as permissões.");
            btn.disabled = false;
            btn.innerText = "Tentar novamente";
        });
};

window.pararCamera = () => {
    if (html5QrCodeScanner) {
        html5QrCodeScanner.stop().then(() => {
            document.getElementById('reader').innerHTML = "";
            const btn = document.getElementById('btnIniciarCamera');
            btn.style.display = 'block';
            btn.disabled = false;
            btn.innerText = "Escanear QR Code";
        }).catch(err => console.error(err));
    }
};

// --- MÁSCARAS DE INPUT (FORMATAÇÃO AUTOMÁTICA) ---

window.mascaraCPF = (i) => {
    let v = i.value.replace(/\D/g, ""); // Remove tudo que não é dígito
    if (v.length > 11) v = v.slice(0, 11); // Limita a 11 números
    
    // Coloca ponto e traço: 000.000.000-00
    i.value = v.replace(/(\d{3})(\d)/, "$1.$2")
               .replace(/(\d{3})(\d)/, "$1.$2")
               .replace(/(\d{3})(\d{1,2})$/, "$1-$2");
}

window.mascaraTelefone = (i) => {
    let v = i.value.replace(/\D/g, "");
    if (v.length > 11) v = v.slice(0, 11);
    
    // Coloca parênteses e traço: (00) 00000-0000
    if (v.length > 10) {
        i.value = v.replace(/^(\d\d)(\d{5})(\d{4}).*/, "($1) $2-$3");
    } else {
        i.value = v.replace(/^(\d\d)(\d{4})(\d{0,4}).*/, "($1) $2-$3");
    }
}

window.validarDia = (i) => {
    let v = parseInt(i.value);
    if (v < 1) i.value = 1;
    if (v > 31) i.value = 31;
    // Remove caracteres não numéricos
    i.value = i.value.replace(/[^0-9]/g, '');
}

// --- FUNÇÃO DE BACKUP (EXCEL) ---
window.exportarExcel = () => {
    if(todosImoveis.length === 0) return alert("Nenhum imóvel para exportar.");

    // 1. Cabeçalho da Planilha
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "Nome do Imóvel;Tipo;Valor (R$);Status;Inquilino;CPF;Telefone;Vencimento;Prazo;Inicio Contrato\n";

    // 2. Linhas de Dados
    todosImoveis.forEach(item => {
        const i = item.data;
        
        // Trata campos vazios para não quebrar a planilha
        const nome = i.nome || "-";
        const tipo = i.tipo || "-";
        const valor = (i.valor || 0).toString().replace('.', ','); // Troca ponto por vírgula pro Excel BR
        const status = i.alugado ? "Alugado" : "Livre";
        const inq = i.inquilino || "-";
        const cpf = i.cpf || "-";
        const tel = i.telefone || "-";
        const venc = i.diaVencimento || "-";
        const prazo = i.prazoContrato ? `${i.prazoContrato} meses` : "-";
        
        // Formata data de inicio se existir
        let inicio = "-";
        if(i.dataInicio) {
            const partes = i.dataInicio.split('-'); // aaaa-mm-dd
            inicio = `${partes[2]}/${partes[1]}/${partes[0]}`;
        }

        // Monta a linha
        csvContent += `${nome};${tipo};${valor};${status};${inq};${cpf};${tel};${venc};${prazo};${inicio}\n`;
    });

    // 3. Download do Arquivo
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Backup_NJ_Imoveis_${new Date().toLocaleDateString('pt-BR').replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}